// 🔻 ResizeObserver 오류 무시 (브라우저 경고 제거)
const ignoreROError = (e: ErrorEvent | PromiseRejectionEvent) => {
  const message = (e as ErrorEvent).message || (e as PromiseRejectionEvent).reason?.message
  if (
    message?.includes("ResizeObserver loop") ||
    message?.includes("ResizeObserver loop completed")
  ) {
    e.stopImmediatePropagation()
  }
}

window.addEventListener("error", ignoreROError)
window.addEventListener("unhandledrejection", ignoreROError)


