<template>
  <div class="wrapper">
    <ul class="toolbar" ref="dock">
        <li v-for="(icon, i) in icons" :key="i" class="toolbarItem">
        <component
            :is="icon.external ? 'a' : 'router-link'"
            :to="!icon.external ? icon.link : null"
            :href="icon.external ? icon.link : null"
            class="toolbarLink"
            rel="noopener"
        >
            <img class="toolbarImg" :src="icon.src" />
        </component>
        </li>
    </ul>
  </div>
</template>

<script setup>
import { ref, onMounted, onBeforeUnmount } from 'vue'
import gsap from 'gsap'

import logo1 from '@/assets/docktoolbar/coverletter.png'
import logo2 from '@/assets/docktoolbar/about.png'
import logo3 from '@/assets/docktoolbar/workflow.png'
import logo4 from '@/assets/docktoolbar/samsungbiologics.png'
import logo5 from '@/assets/docktoolbar/uxengineering.png'
import logo6 from '@/assets/docktoolbar/figma.png'
import logo7 from '@/assets/docktoolbar/design.png'
import logo8 from '@/assets/docktoolbar/planningdocument.png'

const icons = [
  { src: logo1, link: "/coverletter" },
  { src: logo2, link: "/about" },
  { src: logo3, link: "/workflow" },
  { src: logo4, link: "/samsungbiologics" },
  { src: logo5, link: "/uxui" },
  { src: logo6, link: "/figmadesign" },
  { src: logo7, link: "/mockupdesign" },
  { src: logo8, link: "/planningdocument" },
]


const dock = ref(null)
let iconEls = []
let firstIcon = null

const min = 48
const max = 100
const bound = min * Math.PI

function updateIcons(pointer) {
  iconEls.forEach((icon, i) => {
    let distance = (i * min + min / 2) - pointer
    let x = 0
    let scale = 1

    if (-bound < distance && distance < bound) {
      const rad = distance / min * 0.5
      scale = 1 + (max / min - 1) * Math.cos(rad)
      x = 2 * (max - min) * Math.sin(rad)
    } else {
      x = (-bound < distance ? 2 : -2) * (max - min)
    }

    gsap.to(icon, { duration: 0.3, x, scale })
  })
}

function onMove(e) {
  const offset =
    dock.value.getBoundingClientRect().left + firstIcon.offsetLeft
  updateIcons(e.clientX - offset)
}

function onLeave() {
  gsap.to(iconEls, { duration: 0.3, scale: 1, x: 0 })
}

onMounted(() => {
  iconEls = dock.value.querySelectorAll('.toolbarItem')
  firstIcon = iconEls[0]

  gsap.set(iconEls, { transformOrigin: '50% 120%', height: 40 })
  gsap.set(dock.value, { position: 'relative', height: 60 })

  dock.value.addEventListener('mousemove', onMove)
  dock.value.addEventListener('mouseleave', onLeave)
})

onBeforeUnmount(() => {
  dock.value.removeEventListener('mousemove', onMove)
  dock.value.removeEventListener('mouseleave', onLeave)
})
</script>

<style scoped>
.wrapper {
  position: fixed;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  justify-content: center;
  z-index: 999;
}

.toolbar {
  display: inline-flex;
  align-items: flex-end;
  height: 40px;
  padding: 10px;
  background: rgba(55, 66, 77, 0.25);
  border-radius: 12px 12px 0 0;
  list-style: none;
  margin: 0;
}

.toolbarItem {
  width: 40px;
  height: 40px;
  margin: 0 4px;
  cursor: pointer;
}

.toolbarLink {
  display: block;
  height: 100%;
}

.toolbarImg {
  width: 100%;
  height: 100%;
  object-fit: contain;
  /* border-radius: 50%; */
}
</style>
